% Script to extract step data from data generated by simulink
clear p i j

% Displays characteristic values for step responses over a chosen timeframe
% The data will be stored in the workspace as a cell array with chosen name
% Format:
%         {"Signal Label", [Overshoot, SettlingTime, ErrorAtEndOfWindow]}
%
% Responses can be stored in one or multiple structs. Each struct should
% include a reference on the last channel.



p.simout = [nominal, robust];
p.time_start = 0.7;
p.time_stop  = 3;
p.save_name = "SS_SRL_nominalRobust_data_motor";
% =========================================================================

% change the timewindow
if p.time_start >= p.simout(1).time(end)
    p.time_start = 0;
end
if p.time_stop == 0
    p.time_stop = p.simout(1).time(end);
end

p.idx = {};
for i=1:length(p.simout)
    p.idx{i} = find((p.simout(i).time >= p.time_start & ...
                     p.simout(i).time <= p.time_stop));
    p.simout(i).time = p.simout(i).time - p.time_start;
end

p.num_signals = 0;
% loop over all provided datasets
for i=1:length(p.simout)
    p.num_signals = length(p.simout(i).signals)-1;
end

% Preallocate a cellarray
p.results = cell(p.num_signals, 2);

p.idx_loop = 1;
% loop over all provided datasets
for i=1:length(p.simout)
    % loop over all signals in the datasets
    for j = 1:length(p.simout(i).signals)-1

        % display the current signal
        disp(p.simout(i).signals(j).label)

        % get the reference value for the considered window
        p.ref_vals = p.simout(i).signals(end).values(p.idx{i});
        p.ref = p.ref_vals(end);
        
        % extract the step info
        p.curr_vals = p.simout(i).signals(j).values(p.idx{i});
        p.sInfo = stepinfo(p.curr_vals, ...
                           p.simout(i).time(p.idx{i}), ...
                           p.ref, ...
                           'SettlingTimeThreshold', 0.05);
        p.Mp = p.sInfo.Overshoot;
        p.ts = p.sInfo.SettlingTime;
        p.ess = (p.curr_vals(end)-p.ref)/p.ref;

        % display the stepinfo
        disp("  M_p  |  t_s  |  e_ss")
        fprintf(" %.3f & %.3f & %.3f \n",p.Mp, p.ts, p.ess)
        disp("-----------------------")

        % store the data
        p.results{p.idx_loop,1} = p.simout(i).signals(j).label;
        p.results{p.idx_loop,2} = [p.Mp, p.ts, p.ess];
        p.idx_loop = p.idx_loop+1;
    end
end

% actually store the data
assignin("base", p.save_name, p.results);